DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role; END IF; END $$;
CREATE TABLE users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id TEXT,name TEXT,role TEXT);
CREATE TABLE po_master(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),po_number TEXT UNIQUE,shirt_qty INT,trouser_qty INT,dupatta_qty INT,shirt_meters_issued NUMERIC DEFAULT 0,trouser_meters_issued NUMERIC DEFAULT 0,dupatta_meters_issued NUMERIC DEFAULT 0,status TEXT DEFAULT 'Active',article_name TEXT,collection_name TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),po_date DATE,delivery_date DATE);
CREATE TABLE stitchers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),stitcher_code CHAR(4) UNIQUE,name TEXT,status TEXT DEFAULT 'Active',worker_type TEXT DEFAULT 'Stitching');
CREATE TABLE cmt_rates(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),po_number TEXT UNIQUE,status TEXT,cutting NUMERIC DEFAULT 0,shirt NUMERIC DEFAULT 0,trouser NUMERIC DEFAULT 0,dupatta NUMERIC DEFAULT 0,patching NUMERIC DEFAULT 0,fs_clipping NUMERIC DEFAULT 0,fs_heming NUMERIC DEFAULT 0,fs_tussling NUMERIC DEFAULT 0,fs_pressing NUMERIC DEFAULT 0,ft_clipping NUMERIC DEFAULT 0,ft_heming NUMERIC DEFAULT 0,ft_pressing NUMERIC DEFAULT 0,ft_patching NUMERIC DEFAULT 0,fd_heming NUMERIC DEFAULT 0,fd_tussling NUMERIC DEFAULT 0,fd_pressing NUMERIC DEFAULT 0,fd_patching NUMERIC DEFAULT 0,quality_packing NUMERIC DEFAULT 0,color_design TEXT,remarks TEXT,submitted_by TEXT,submitted_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW(),approved_by_accounts TEXT,accounts_approved_at TIMESTAMPTZ,approved_by_ceo TEXT,ceo_approved_at TIMESTAMPTZ,accounts_remarks TEXT,ceo_remarks TEXT);
CREATE TABLE stitcher_allocations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),po_number TEXT,component TEXT,stitcher_id UUID,stitcher_code CHAR(4),stitcher_name TEXT,module_type TEXT DEFAULT 'Stitching',qty_allocated NUMERIC DEFAULT 0,qty_returned NUMERIC DEFAULT 0,qty_accepted NUMERIC DEFAULT 0,qty_rework NUMERIC DEFAULT 0,qty_rejected NUMERIC DEFAULT 0,allocation_date DATE DEFAULT CURRENT_DATE,status TEXT,remarks TEXT,allocated_by TEXT,last_updated_by TEXT,last_updated_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE cmt_payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),po_number TEXT,stitcher_id UUID,stitcher_code CHAR(4),stitcher_name TEXT,component TEXT,department TEXT,operation TEXT,qty_claimed NUMERIC,rate NUMERIC,amount NUMERIC,week_ending DATE,payment_status TEXT DEFAULT 'Pending',verified_by TEXT,verified_at TIMESTAMPTZ,payment_date DATE,entry_date DATE,worker_type TEXT,flexible_payment BOOLEAN,color TEXT,remarks TEXT,submitted_by TEXT,submitted_at TIMESTAMPTZ);
CREATE TABLE advances(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),stitcher_code CHAR(4),stitcher_name TEXT,amount NUMERIC,week_ending DATE,added_by TEXT,note TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
